// scripts/_wrap-client-bundle.mjs
// Wrap the esbuild CJS output into the DSH webview module-loader format:
//   window.__ModuleLoader__.load({ id, factory(require){...} })
// Used by scripts/build-client.mjs (which documents the contract) and this
// CLI-driven mirror for sandboxes where the esbuild JS API cannot spawn.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const rawPath = join(root, 'lib', 'client.raw.cjs.js')
const outPath = join(root, 'lib', 'client.js')
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const packageName = pkg.name

const raw = readFileSync(rawPath, 'utf8')
const wrapped = `/* dsh-edge-agent client bundle — generated by scripts/build-client.mjs.
   Format: DSH webview module-system registration (classic script). */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(packageName)},
  factory: function (require) {
    var module = { exports: {} };
    var exports = module.exports;
    (function () {
${raw.replace(/\n+$/u, '')}
    })();
    return module.exports;
  },
});
`
writeFileSync(outPath, wrapped)
console.log(`[wrap] lib/client.js = ${(Buffer.byteLength(wrapped) / 1024).toFixed(1)} KB (id=${packageName})`)
